import {getAction,getCharacter} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const trainingPhysicalScenarios=['training-warrior-equal','training-magic-equal','training-warrior-success','training-magic-success','training-warrior-fate','training-magic-fate','training-warrior-forced','training-magic-forced','training-warrior-reroll','training-magic-reroll','training-warrior-lan','training-magic-lan','training-warrior-ii','training-magic-ii','training-warrior-lan-ordinary','training-magic-lan-ordinary','training-warrior-lan-fate','training-magic-lan-fate','training-warrior-artifact','training-magic-artifact','training-warrior-before','training-magic-before','training-warrior-after','training-magic-after','training-warrior-decline','training-magic-decline','training-warrior-suppressed','training-magic-suppressed','training-warrior-stopped','training-magic-stopped'] as const;
export type TrainingPhysicalScenario=typeof trainingPhysicalScenarios[number];
export function isTrainingPhysicalScenario(name:string):name is TrainingPhysicalScenario{return (trainingPhysicalScenarios as readonly string[]).includes(name);}
export function trainingMode(name:TrainingPhysicalScenario){const warrior=name.includes('-warrior-'),ii=name.endsWith('-ii'),suppressed=name.endsWith('-suppressed'),stopped=name.endsWith('-stopped'),lancelot=name.includes('-lan')||ii||suppressed;return {warrior,ii,suppressed,stopped,lancelot,dedicated:lancelot&&!name.endsWith('-lan-ordinary'),fate:name.endsWith('-fate'),artifact:name.endsWith('-artifact'),blood:name.endsWith('-before')||name.endsWith('-after'),card:warrior?'a2-p03-r2c2' as const:'a2-p03-r2c3' as const,stat:warrior?'warrior_level' as const:'magic_level' as const,attachment:warrior?'a2-p03-r2c1':'a2-p03-r3c1'};}
/** Real setup, optional ordinary attachment installation/fullturns, actual Lia
 * reveal and Lancelot II transform, or prior Confusion/Hypnosis and recovery. */
export function makeTrainingPhysicalScenario(name:TrainingPhysicalScenario,players:{id:string;name:string}[],options:{level?:number;endurance?:number;beforeStart?:boolean}={}){
 const m=trainingMode(name),prior=m.suppressed||m.stopped;let s=createGame(players,entropy(),{startingSeat:prior?3:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.lancelot?'聖騎士ランスロット':'大神官ジル','魔導王ガイナス',m.lancelot?getCharacter('c2-p03-r1c2')!.name:'小妖精のチャム','占星術師のアルセイル'][i]!);for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};const future=getCharacter(m.ii?'c2-p07-r1c1':s.players[a]!.characterId)!;s.players[a]!.permanent![m.stat]=(options.level??6)-future.base_stats[m.stat];s.players[a]!.permanent!.spirit!+=6-gameStats(s,a).spirit;if(options.endurance!==undefined)s.players[a]!.permanent!.endurance!+=options.endurance-gameStats(s,a).endurance;
 const keep=[takeCard(s,a,m.card),takeCard(s,a,'a2-p02-r1c1'),takeCard(s,b,'a2-p24-r1c2'),takeCard(s,d,'a2-p02-r2c3'),takeCard(s,d,'a2-p02-r1c3')];if(m.artifact)keep.push(takeCard(s,a,m.attachment));if(prior)keep.push(takeCard(s,d,m.suppressed?'a2-p13-r1c2':'a2-p13-r2c1'));for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];if(m.blood){takeCard(s,a,'a2-p01-r1c3');s.players[a]!.hand=s.players[a]!.hand.filter(id=>id!=='a2-p01-r1c3');s.deck.unshift('a2-p01-r1c3');}s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`TRAINING_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('TRAINING_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('TRAINING_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<500;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('TRAINING_FIXTURE_WINDOW');}
 function start(id:string,face=1){act(id,{type:'START_TURN'});settle(face);if(s.phase==='draw'){act(id,{type:'CHOOSE_DRAW',draw:false});settle();}}
 function end(id:string){if(s.phase==='action')act(id,{type:'PASS_ACTION'});if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>!keep.includes(x)).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});settle();}
 for(const id of [a,b,c,d])act(id,{type:'PASS_SETUP'});if(options.beforeStart)return s;
 if(prior){start(d);act(d,{type:'ATTACK',cardInstanceId:m.suppressed?'a2-p13-r1c2':'a2-p13-r2c1',targetIds:[a],dedicated:false});settle(6);if(!s.players[a]!.statuses?.some(x=>x.kind===(m.suppressed?'ability-disabled':'stopped')))throw Error('TRAINING_NO_STATUS');end(d);}start(a,prior?6:1);
 if(m.ii){act(c,{type:'REVEAL_CHARACTER'});settle();act(a,{type:'USE_LIFECYCLE_ABILITY',ability:'lancelot-transform'});settle();if(s.players[a]!.characterId!=='c2-p07-r1c1')throw Error('TRAINING_NO_TRANSFORM');}
 if(m.artifact){act(a,{type:'PLAY_TURN_CARD',cardInstanceIds:[m.attachment]});settle();end(a);for(const id of [b,c,d]){start(id);end(id);}start(a);}return s;
}
